svg.script:
//
(function () {
  var svg = document.getElementById('bc-sv');
  if (!svg) return;
  var iT = svg.querySelector('#bc-it');
  var iD = svg.querySelector('#bc-id');

  var DESCS = {
    pivot:   ['Pivot Hole — Ø10 H7',
              'Primary rotation axis. H7 tolerance ensures a precision fit with the pivot shaft. Located 25 mm from left edge, 10 mm from top.'],
    bearing: ['Input Arm — Ø15, R20 Boss',
              'Input rod connection. R20 clearance boss clears the rotating link. Centre is 84.7 mm from the pivot axis centre.'],
    slot:    ['Output Slot — R12.5 × R7.5',
              'Pin-in-slot output connection. Elongated slot allows ±7.5 mm of alignment travel during assembly on the lower arm.'],
    body:    ['Bell Crank Body — R75 Sweep',
              'Structural body. R75 inner arc reduces mass while maintaining bending stiffness between both link attachment points.'],
    topview: ['Top Profile — 116.87 mm Overall',
              'Uniform-section extrusion profile. Total length 116.87 mm; narrow width maximises stiffness-to-weight ratio.']
  };

  function reset() {
    svg.querySelectorAll('.bc-ring.lit').forEach(function (r) { r.classList.remove('lit'); });
    if (iT) iT.textContent = '';
    if (iD) iD.textContent = 'Hover the highlighted features to explore the bell crank geometry';
  }

  svg.querySelectorAll('.bc-feat').forEach(function (g) {
    var id  = g.dataset.id;
    var ring = g.querySelector('.bc-ring');
    function on() {
      reset();
      if (ring) ring.classList.add('lit');
      var d = DESCS[id] || ['', ''];
      if (iT) iT.textContent = d[0];
      if (iD) iD.textContent = d[1];
    }
    g.addEventListener('mouseenter', on);
    g.addEventListener('click',      on);
    g.addEventListener('mouseleave', reset);
  });

  svg.addEventListener('click', function (e) {
    if (!e.target.closest('.bc-feat')) reset();
  });

  // Build-up: ping each ring in sequence
  if (window.matchMedia('(prefers-reduced-motion:reduce)').matches) {
    svg.querySelectorAll('.bc-ring').forEach(function (r) { r.classList.add('ready'); });
    return;
  }
  svg.querySelectorAll('.bc-ring').forEach(function (r, i) {
    setTimeout(function () { r.classList.add('ready'); }, 400 + i * 500);
  });
})();
//
